// 1. Capturamos los datos de los tres nodos de Sheets
const estudiantes = $("Leer Estudiantes").all(); // Lista de estudiantes registrados
const tutores = $("Leer Tutores").all(); // Lista de tutores
const tutorias = $("Leer Tutorias").all(); // Lista de tutorías agendadas

// 2. Mapeamos los tutores en un objeto rápido (id_tutor -> Nombre)
const mapaTutores = {};
tutores.forEach(t => {
  mapaTutores[t.json.id_tutor] = t.json.nombre;
});

// 3. Calculamos la fecha actual en formato "YYYY-MM-DD" en la zona horaria local
const hoy = new Date();
const offset = hoy.getTimezoneOffset();
const fechaHoy = new Date(hoy.getTime() - (offset * 60 * 1000)).toISOString().split('T').at(0);

// 4. Filtramos las tutorías que sean para HOY y estén en estado "Asignada"
const tutoriasDeHoy = tutorias.filter(t => {
  let fechaTut = t.json.fecha;

  // Limpiamos formato si tiene corchetes o comillas de residuos anteriores
  if (fechaTut && typeof fechaTut === 'string' && fechaTut.startsWith("[")) {
    try { 
      const arr = JSON.parse(fechaTut);
      fechaTut = Array.isArray(arr) ? arr.at(0) : arr; 
    } catch (e) {}
  }
  return fechaTut === fechaHoy && t.json.estado === "Asignada";
});

// 5. Construimos el mensaje estético consolidado (será el mismo para todos)
let mensaje = "";
if (tutoriasDeHoy.length === 0) {
  mensaje = "📭 *REPORTE DIARIO DE TUTORÍAS*\n\nNo hay tutorías programadas para el día de hoy (" + fechaHoy + ") en el sistema.\n\nEl sistema está libre y listo para recibir nuevos agendamientos. 🤖";
} else {
  mensaje = "📋 *REPORTE DIARIO DE TUTORÍAS (HOY: " + fechaHoy + ")*\n";
  mensaje += "Se encontraron *" + tutoriasDeHoy.length + "* tutorías asignadas para el día de hoy en el sistema:\n\n";

  tutoriasDeHoy.forEach((t, index) => {
    const nombreTutor = mapaTutores[t.json.id_tutor] || "Tutor asignado";
    mensaje += "🔔 *Tutoría #" + (index + 1) + "* (Ref: _" + t.json.id_tutoria + "_)\n";
    mensaje += "📚 *Materia:* " + t.json.materia + "\n";
    mensaje += "👨‍🏫 *Tutor:* " + nombreTutor + "\n";
    mensaje += "⏰ *Horario:* " + t.json.hora_inicio + " - " + t.json.hora_fin + "\n";
    mensaje += "🔗 *Aula Virtual:* " + (t.json.url_de_conexion || "link_here") + "\n";
    mensaje += "--------------------------------\n\n";
  });

  mensaje += "🤖 _Este reporte diario ha sido consolidado de manera automática desde la base de datos de TutorBot._";
}

// 6. Multiplicamos la salida: Generamos un elemento independiente por cada estudiante registrado
// n8n procesará de forma nativa e iterará sobre cada elemento al llegar al nodo de Telegram
return estudiantes.map(est => {
  return {
    json: {
      id_estudiante: est.json.id_estudiante, // ID único de Telegram del alumno
      nombre_estudiante: est.json.nombre_estudiante,
      mensaje_reporte: mensaje
    }
  };
});
